const BOOK_FOODS=[];
function bookFood(name,basis_value,basis_unit,kcal,protein,cho,fat,category,extra={}){BOOK_FOODS.push({id:uid(),type:'food',name,basis_value,basis_unit,kcal,protein,cho,fat,mct:0,calcium:0,magnesium:0,phosphorus:0,sodium:0,potassium:0,iron:0,zinc:0,source:'Nutrition book exchange list',category,...extra})}
// Milk: 1 exchange = CHO 12 g, protein 8 g; energy/fat vary by milk type.
bookFood('นมสดธรรมดา',240,'mL',150,8,12,8,'milk');
bookFood('นมสดพร่องมันเนย',240,'mL',120,8,12,5,'milk');
bookFood('นมสดขาดมันเนย',240,'mL',90,8,12,1,'milk');
