  text=text
    .replace(/[\u201C\u201D\u201E\u201F\u275D\u275E\u301D\u301E\u301F\u00AB\u00BB\uFF02]/g,'\"')
    .replace(/[\u2018\u2019\u201A\u201B\u2032\u2035]/g,"'")
    .replace(/\u00a0/g,' ')
