let designDraft=null,designDirty=false;
function ensureDesignDraft(){if(!designDraft)designDraft=clone(state.dietDesign||blankDietDesign());return designDraft}
function normalizeConstraintMode(r){if(!r)return 'auto';if(!r.constraintMode)r.constraintMode=r.locked?'locked':'auto';r.locked=r.constraintMode==='locked';return r.constraintMode}
function rowIsConstrained(r){return ['manual','locked'].includes(normalizeConstraintMode(r))}
function constraintModeOptions(r){const v=normalizeConstraintMode(r);return `<option value="auto" ${v==='auto'?'selected':''}>Auto</option><option value="manual" ${v==='manual'?'selected':''}>Manual</option><option value="locked" ${v==='locked'?'selected':''}>Locked</option>`}
function setManualAfterAmountEdit(r){if(normalizeConstraintMode(r)!=='locked'){r.constraintMode='manual';r.locked=false}}
function normalizeDietCapacity(d){(d?.dietItems||[]).forEach(r=>{if(r.maxAmount===undefined)r.maxAmount='';normalizeConstraintMode(r);if(!r.roundRule)r.roundRule=defaultRoundRule(r,'diet')});(d?.formulaPlans||[]).forEach(p=>{normalizeConstraintMode(p);(p.fortifiers||[]).forEach(normalizeConstraintMode)});(d?.modular?.components||[]).forEach(normalizeConstraintMode);return d}
function resetDesignDraft(){designDraft=normalizeDietCapacity(clone(state.dietDesign||blankDietDesign()));designDirty=false}
