function deletePnCase(){const c=state.cases.find(x=>x.id===state.activeCaseId);if(!c)return;const label=pnCaseLabel(c);if(!confirm(`Delete PN case “${label}”? This deletes the whole case stored in this browser.`))return;state.cases=state.cases.filter(x=>x.id!==state.activeCaseId);if(!state.cases.length)state.cases=[blankCase()];const n=state.cases[0];state.activeCaseId=n.id;state.patient=clone(n.patient||blankCase().patient);state.requirements=clone(n.requirements||blankCase().requirements);state.dietDesign=clone(n.dietDesign||blankDietDesign());state.pn=clone(n.pn||blankPn());state.pnif=clone(n.pnif||{});state.meals=clone(n.meals||[]);state.modular=clone(n.modular||blankCase().modular);state.lastSummary=n.lastSummary||null;pnDirty=false;saveState();renderPn()}
function clearPnBoxes(){const oldId=ensurePn().patient?.caseId||'';if(!confirm('Clear all PN calculation boxes for this case? The anonymous name / ID will be kept.'))return;state.pn=blankPn();state.pn.patient.caseId=oldId;pnDirty=true;saveState();pnDirty=false;renderPn()}
function renderPn(){if(!$('pnPatientSummary'))return;const p=ensurePn(),pd=p.patient||{},w=num(pd.weight),maint=hollidaySegarDaily(w),days=patientAgeDaysForPn();renderPnCaseSelector();if($('pnCaseId'))$('pnCaseId').value=pd.caseId??'';$('pnSaveStatus').innerHTML=pnDirty?'<span class="dirty-pill">Unsaved PN changes</span>':'<span class="saved-pill">Saved</span>';const ageBits=[];if(pd.ageYears!==''&&pd.ageYears!=null)ageBits.push(`${num(pd.ageYears)} y`);if(pd.ageMonths!==''&&pd.ageMonths!=null)ageBits.push(`${num(pd.ageMonths)} m`);if(pd.ageDays!==''&&pd.ageDays!=null)ageBits.push(`${num(pd.ageDays)} d`);$('pnPatientSummary').innerHTML=`<div class="summary-grid"><div class="metric">Birth status<b>${pd.birthStatus==='preterm'?'Preterm':'Term'}</b></div><div class="metric">PN age<b>${ageBits.length?esc(ageBits.join(' ')):'—'}</b></div><div class="metric">PN weight<b>${w?round(w,2)+' kg':'—'}</b></div><div class="metric">Holliday–Segar equivalent<b>${maint?round(maint,0)+' mL/day ≈ kcal/day':'—'}</b><span>Used only for mEq/100 kcal Na/K conversion</span></div></div>`;const patientVals={pnBirthStatus:pd.birthStatus,pnAgeYears:pd.ageYears,pnAgeMonths:pd.ageMonths,pnAgeDays:pd.ageDays,pnWeight:pd.weight};Object.entries(patientVals).forEach(([id,v])=>{if($(id))$(id).value=v??''});const vals={pnPhase:p.phase,pnNeonatalPhase:p.neonatalPhase,pnVenousAccess:p.venousAccess,pnDexMode:p.dexMode,pnNaUnit:p.naUnit,pnKUnit:p.kUnit,pnIleProduct:p.ileProduct,pnVitaminMode:p.vitaminMode,pnPhosProduct:p.phosProduct,pnTraceProduct:p.traceProduct,pnAaProduct:p.aaProduct,pnRate:p.rate,pnMixedVolume:p.mixedVolume,pnOsmolarity:p.osmolarity,pnNaClAlloc:p.naClAlloc,pnNaAcAlloc:p.naAcAlloc,pnKClAlloc:p.kClAlloc,pnKAcAlloc:p.kAcAlloc,pnHeparinUnitMl:p.heparinUnitMl};Object.entries(vals).forEach(([id,v])=>{if($(id))$(id).value=v??''});const map={pnFluidMl:'fluidMl',pnReqEnergy:'energy',pnReqProtein:'protein',pnReqGir:'gir',pnReqDexGkg:'dexGkg',pnReqDexPct:'dexPct',pnReqFat:'fat',pnReqNa:'sodium',pnReqK:'potassium',pnReqCa:'calcium',pnReqP:'phosphorus',pnReqMg:'magnesium',pnReqZinc:'zinc'};pnSyncDextrose(p.dexMode||'gir');Object.entries(map).forEach(([id,k])=>$(id).value=p.requirements[k]??'');['gir','gkg','percent'].forEach(mode=>{const id=mode==='gir'?'pnReqGir':mode==='gkg'?'pnReqDexGkg':'pnReqDexPct',el=$(id);if(el){const calc=p.dexMode!==mode;el.readOnly=calc;el.classList.toggle('calculated-input',calc);el.classList.remove('readonly-input');el.setAttribute('aria-readonly',calc?'true':'false')}});$('pnPeripheralOverride').checked=!!p.peripheralOverride;const estOsm=pnEstimatedOsmolarity().value;if($('pnOsmolarity')){$('pnOsmolarity').value=estOsm?round(estOsm,1):'';$('pnOsmolarity').readOnly=true;$('pnOsmolarity').placeholder='Calculated automatically'};$('pnPeripheralOverrideWrap').style.display=p.venousAccess==='peripheral'&&estOsm>900?'block':'none';const na=pnNaKTarget('na'),kk=pnNaKTarget('k');$('pnElectrolyteEquivalent').textContent=w?`Equivalent normalized targets: Na ${round(na,3)} mmol/kg/day • K ${round(kk,3)} mmol/kg/day • 1 mmol Na/K = 1 mEq. Holliday–Segar equivalent ${round(maint,0)} kcal/day.`:'';renderPnGuideline();pnAutoCalculateProducts();renderPnProducts();renderPnRecheck()}
